// Core tests: the 17 literal core cases from the fixed spec's
// fixtures.json (vendored verbatim at test/fixtures.json from spec
// candidate a07fd30d844486b74683d38217d62781526033e9; expected values
// taken verbatim, never generated by the product), plus independently
// derived endpoint, grammar, and validation-order cases. The extra
// success expectations below were produced by an independent scratch
// implementation of the SPEC's stated rules (integer JDN algorithms,
// positive-modulo age, centred-segment phase index), which itself
// reproduces all 12 literal success fixtures exactly.

import assert from "node:assert/strict";
import test from "node:test";
import { run, SYNODIC_MONTH } from "../public/js/core/moon.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

// Independently derived: 2000 is divisible by 400, so 2000-02-29 is a
// real date (the century rule's other side from 1900-02-29 below).
test("derived: 2000-02-29 is a real leap day", () => {
  assert.deepEqual(run({ date: "2000-02-29", utcOffset: "+08:00" }), {
    ok: true,
    result: {
      julianDay: 2451604,
      ageDays: 24.4,
      phaseIndex: 7,
      phaseZh: "殘月",
      phaseEn: "Waning Crescent",
      illuminationPercent: 27.2,
      daysToNextNewMoon: 5.2,
      nextNewMoonDate: "2000-03-05",
      nextNewMoonDateLocal: "2000-03-05",
      daysToNextFullMoon: 19.9,
      nextFullMoonDate: "2000-03-20",
      nextFullMoonDateLocal: "2000-03-20",
    },
  });
});

// Independently derived: the pinned offset endpoints -12:00 and
// +14:00 are legal; they move only the local event dates.
test("derived: offset endpoints -12:00 and +14:00", () => {
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "-12:00" }), {
    ok: true,
    result: {
      julianDay: 2461354,
      ageDays: 29.3,
      phaseIndex: 0,
      phaseZh: "新月",
      phaseEn: "New Moon",
      illuminationPercent: 0.1,
      daysToNextNewMoon: 0.3,
      nextNewMoonDate: "2026-11-09",
      nextNewMoonDateLocal: "2026-11-09",
      daysToNextFullMoon: 15.0,
      nextFullMoonDate: "2026-11-24",
      nextFullMoonDateLocal: "2026-11-24",
    },
  });
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "+14:00" }), {
    ok: true,
    result: {
      julianDay: 2461354,
      ageDays: 29.3,
      phaseIndex: 0,
      phaseZh: "新月",
      phaseEn: "New Moon",
      illuminationPercent: 0.1,
      daysToNextNewMoon: 0.3,
      nextNewMoonDate: "2026-11-09",
      nextNewMoonDateLocal: "2026-11-10",
      daysToNextFullMoon: 15.0,
      nextFullMoonDate: "2026-11-24",
      nextFullMoonDateLocal: "2026-11-25",
    },
  });
});

// Independently derived: a 45-minute offset is a legal 15-minute
// multiple and shifts nothing across a date boundary here.
test("derived: +05:45 quarter-hour offset", () => {
  const outcome = run({ date: "2026-11-09", utcOffset: "+05:45" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.nextNewMoonDateLocal, "2026-11-09");
  assert.equal(outcome.result.nextFullMoonDateLocal, "2026-11-24");
});

test("1900-02-29 is not a real date (century rule)", () => {
  assert.deepEqual(run({ date: "1900-02-29", utcOffset: "+08:00" }), {
    ok: false,
    error: { code: "INVALID_DATE", field: "date", row: null },
  });
});

test("2101-01-01 is just past the range", () => {
  assert.deepEqual(run({ date: "2101-01-01", utcOffset: "+08:00" }), {
    ok: false,
    error: { code: "RANGE", field: "date", row: null },
  });
});

test("offset +14:15 exceeds the total range", () => {
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "+14:15" }), {
    ok: false,
    error: { code: "RANGE", field: "utcOffset", row: null },
  });
});

test("offset -12:15 exceeds the total range", () => {
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "-12:15" }), {
    ok: false,
    error: { code: "RANGE", field: "utcOffset", row: null },
  });
});

test("empty offset is EMPTY on utcOffset", () => {
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "" }), {
    ok: false,
    error: { code: "EMPTY", field: "utcOffset", row: null },
  });
});

test("grammar codes: DATE_FORMAT and OFFSET_FORMAT", () => {
  assert.deepEqual(run({ date: "2026-11-9", utcOffset: "+08:00" }), {
    ok: false,
    error: { code: "DATE_FORMAT", field: "date", row: null },
  });
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "08:00" }), {
    ok: false,
    error: { code: "OFFSET_FORMAT", field: "utcOffset", row: null },
  });
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "+8:00" }), {
    ok: false,
    error: { code: "OFFSET_FORMAT", field: "utcOffset", row: null },
  });
});

test("capacity fires before grammar: INPUT_LIMIT", () => {
  assert.deepEqual(run({ date: "2000-01-066", utcOffset: "+08:00" }), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "date", row: null },
  });
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "+08:000" }), {
    ok: false,
    error: { code: "INPUT_LIMIT", field: "utcOffset", row: null },
  });
});

test("unpaired surrogate is UNICODE, checked after capacity", () => {
  assert.deepEqual(run({ date: "2000-01-0\uD800", utcOffset: "+08:00" }), {
    ok: false,
    error: { code: "UNICODE", field: "date", row: null },
  });
  assert.deepEqual(run({ date: "2026-11-09", utcOffset: "+08:0\uDC00" }), {
    ok: false,
    error: { code: "UNICODE", field: "utcOffset", row: null },
  });
});

test("field order: a date error beats any utcOffset error", () => {
  assert.deepEqual(run({ date: "", utcOffset: "bad!" }), {
    ok: false,
    error: { code: "EMPTY", field: "date", row: null },
  });
  assert.deepEqual(run({ date: "2023-02-29", utcOffset: "+99:99" }), {
    ok: false,
    error: { code: "INVALID_DATE", field: "date", row: null },
  });
});

test("schema rejects non-plain shapes", () => {
  const schema = { ok: false, error: { code: "SCHEMA", field: null, row: null } };
  assert.deepEqual(run(null), schema);
  assert.deepEqual(run(["2000-01-06", "+08:00"]), schema);
  assert.deepEqual(run("2000-01-06"), schema);
  assert.deepEqual(run({ date: "2000-01-06" }), schema);
  assert.deepEqual(run({ date: "2000-01-06", utcOffset: "+08:00", extra: "x" }), schema);
  assert.deepEqual(run({ date: 20000106, utcOffset: "+08:00" }), schema);
});

test("schema rejects accessors without invoking them", () => {
  let invoked = false;
  const input = { utcOffset: "+08:00" };
  Object.defineProperty(input, "date", {
    enumerable: true,
    get() {
      invoked = true;
      return "2000-01-06";
    },
  });
  assert.deepEqual(run(input), {
    ok: false,
    error: { code: "SCHEMA", field: null, row: null },
  });
  assert.equal(invoked, false);
});

test("invariant sweep: age stays in [0, S) and outputs stay well-formed", () => {
  const dateShape = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
  for (let year = 1900; year <= 2100; year += 7) {
    for (const [month, day] of [[1, 1], [2, 28], [6, 15], [9, 1], [12, 31]]) {
      const date = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      const outcome = run({ date, utcOffset: "-03:30" });
      assert.equal(outcome.ok, true, date);
      const { result } = outcome;
      assert.ok(result.ageDays >= 0 && result.ageDays < SYNODIC_MONTH, date);
      assert.ok(result.phaseIndex >= 0 && result.phaseIndex <= 7, date);
      assert.ok(result.illuminationPercent >= 0 && result.illuminationPercent <= 100, date);
      assert.ok(dateShape.test(result.nextNewMoonDate), date);
      assert.ok(dateShape.test(result.nextFullMoonDateLocal), date);
    }
  }
});
